/* ---------- apply ---------- */
(function(){
  const warn=[];
  Object.keys(QP).forEach(key=>{const nb=QP[key];const hits=[];
    MODULES.forEach(m=>m.s.forEach(sc=>sc.forEach((b,i)=>{if((b.t==='mcq'||b.t==='multi')&&b.q&&b.q.indexOf(key)>-1)hits.push([sc,i]);})));
    if(hits.length!==1){warn.push(key+' → '+hits.length);return;}hits[0][0][hits[0][1]]=nb;});
  Object.keys(CP).forEach(title=>{let found=0;
    MODULES.forEach(m=>m.s.forEach(sc=>sc.forEach(b=>{if(b.t==='case'&&b.title.startsWith(title)){found++;Object.keys(CP[title]).forEach(id=>{if(b.n[id])b.n[id].ch=CP[title][id];else warn.push(title+' node '+id);});}})));
    if(found!==1)warn.push('case '+title+' → '+found);});
  window.__PATCHWARN=warn;
})();
